draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 50; i++) {
    ctx.beginPath();
    ctx.arc(Math.sin(t + i) * W / 2 + W / 2, Math.sin(t * 2 + i) * H / 2 + H / 2, 2, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}
